#!/usr/bin/env node
/**
 * sync-from-hal0-web.mjs
 *
 * Regenerates the AUTO-GENERATED files in this repo from a checkout of
 * hal0-web, so brand tokens and nav links are never hand-forked here.
 *
 * Source of truth (in hal0-web):
 *   - src/styles/tokens.css   -> scss/_hal0-tokens.scss
 *   - src/data/nav.json       -> javascripts/discourse/lib/hal0-nav-data.js
 *
 * Usage:
 *   node scripts/sync-from-hal0-web.mjs [path-to-hal0-web-checkout]
 *   HAL0_WEB_DIR=/mnt/mintdev/repos/hal0-web node scripts/sync-from-hal0-web.mjs
 *
 * Resolution order for the hal0-web checkout path: CLI arg > HAL0_WEB_DIR
 * env var > ../hal0-web relative to this repo (sibling checkout).
 */
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(__dirname, "..");

const hal0WebDir = resolve(
  process.argv[2] || process.env.HAL0_WEB_DIR || resolve(repoRoot, "../hal0-web")
);

const tokensPath = resolve(hal0WebDir, "src/styles/tokens.css");
const navPath = resolve(hal0WebDir, "src/data/nav.json");

for (const [label, p] of [["tokens.css", tokensPath], ["nav.json", navPath]]) {
  if (!existsSync(p)) {
    console.error(`error: could not find ${label} at ${p}`);
    console.error("Pass the hal0-web checkout path as an argument or set HAL0_WEB_DIR.");
    process.exit(1);
  }
}

// ---------------------------------------------------------------------------
// 1. tokens.css -> scss/_hal0-tokens.scss
// ---------------------------------------------------------------------------

function extractDeclBlock(css, selectorRe) {
  const m = selectorRe.exec(css);
  if (!m) return null;
  const start = m.index + m[0].length;
  const end = css.indexOf("}", start);
  return css.slice(start, end);
}

function parseDecls(block) {
  // NOTE: this regex terminates a value at the first `;`, which is correct
  // for every token in tokens.css today (plain hex/rgba/keyword values with
  // no embedded semicolons). If a future token's value ever legitimately
  // contains a `;` (e.g. a data: URI, or a multi-fallback font stack quoted
  // in a way that includes one), this will silently truncate it — there's
  // no guard against that here, just this warning for whoever hits it.
  const out = [];
  const re = /--([a-z0-9-]+)\s*:\s*([^;]+);/gi;
  let m;
  while ((m = re.exec(block))) {
    out.push([m[1].trim(), m[2].trim()]);
  }
  return out;
}

const tokensCss = readFileSync(tokensPath, "utf8");

const rootBlock = extractDeclBlock(tokensCss, /:root\s*{/);
const lightBlock = extractDeclBlock(tokensCss, /\[data-theme=['"]light['"]\]\s*{/);

if (!rootBlock || !lightBlock) {
  console.error("error: could not locate :root or [data-theme='light'] block in tokens.css");
  process.exit(1);
}

const darkDecls = parseDecls(rootBlock);
const lightDecls = parseDecls(lightBlock);

const renderDecls = (decls, indent = "  ") =>
  decls.map(([name, value]) => `${indent}--${name}: ${value};`).join("\n");

const tokensScss = `// AUTO-GENERATED by scripts/sync-from-hal0-web.mjs — do not edit by hand.
// Source: ${hal0WebDir}/src/styles/tokens.css
// Regenerate with: node scripts/sync-from-hal0-web.mjs [hal0-web-dir]
//
// Dark is the default surface everywhere on the forum (matches hal0-web).
//
// Light overrides ride on \`(prefers-color-scheme: light)\` because that is
// literally the signal Discourse itself switches palettes on — see core's
// application_helper.rb#light_elements_media_query. An earlier version of
// this file keyed off \`html.light-scheme\`, which never matched anything:
// "light-scheme"/"dark-scheme" are classes Discourse puts on the <link>
// elements for the two colour-scheme stylesheets, not on <html>.
//
// Consequence worth knowing: this follows the OS preference only. If the
// forum enables \`interface_color_selector\`, a visitor who manually forces
// light while their OS is dark gets Discourse's light palette but these
// dark tokens. Keep the selector disabled, or bridge the chrome to
// Discourse's own --primary/--secondary variables, before turning it on.

:root {
${renderDecls(darkDecls)}
}

@media (prefers-color-scheme: light) {
  :root {
${renderDecls(lightDecls, "    ")}
  }
}

.hal0-force-light {
${renderDecls(lightDecls)}
}
`;

mkdirSync(resolve(repoRoot, "scss"), { recursive: true });
writeFileSync(resolve(repoRoot, "scss/_hal0-tokens.scss"), tokensScss);
console.log(`wrote scss/_hal0-tokens.scss (${darkDecls.length} dark tokens, ${lightDecls.length} light overrides)`);

// ---------------------------------------------------------------------------
// 2. nav.json -> javascripts/discourse/lib/hal0-nav-data.js
// ---------------------------------------------------------------------------

const nav = JSON.parse(readFileSync(navPath, "utf8"));

// Header nav, minus the forum entry itself (the forum IS this site — it
// gets aria-current on a hard-coded entry in the nav connector, not a
// duplicate link back to itself) and minus anything marked hidden.
const headerLinks = nav.header
  .filter((l) => l.label !== "forum" && !l.hidden)
  .map((l) => ({
    label: l.label,
    href: l.href,
    external: Boolean(l.external),
  }));

const footerColumns = nav.footerColumns.map((col) => ({
  heading: col.heading,
  links: col.links.map((l) => ({
    label: l.label,
    href: l.href,
    external: Boolean(l.external),
  })),
}));

const social = nav.social || [];
const footerBase = (nav.footerBase || []).map((l) => ({
  label: l.label,
  href: l.href,
  external: Boolean(l.external),
}));

const navJs = `// AUTO-GENERATED by scripts/sync-from-hal0-web.mjs — do not edit by hand.
// Source: ${hal0WebDir}/src/data/nav.json
// Regenerate with: node scripts/sync-from-hal0-web.mjs [hal0-web-dir]
//
// hrefs are relative to hal0.dev (site-relative paths like "/docs/...").
// The connectors resolve them against the hal0_web_origin theme setting
// so links work regardless of which host the theme is installed on.

export const HAL0_HEADER_LINKS = ${JSON.stringify(headerLinks, null, 2)};

export const HAL0_FOOTER_COLUMNS = ${JSON.stringify(footerColumns, null, 2)};

export const HAL0_SOCIAL = ${JSON.stringify(social, null, 2)};

export const HAL0_FOOTER_BASE = ${JSON.stringify(footerBase, null, 2)};
`;

writeFileSync(resolve(repoRoot, "javascripts/discourse/lib/hal0-nav-data.js"), navJs);
console.log(`wrote javascripts/discourse/lib/hal0-nav-data.js (${headerLinks.length} header links, ${footerColumns.length} footer columns)`);
